package vn.vht.qtkhcn.identity.domain;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="user_role_assignments")
public class UserRoleAssignment { @Id public UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) public User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="role_id",nullable=false) public Role role; @Column(name="data_scope",nullable=false,length=32) public String dataScope; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="organization_id") public Organization organization; @Column(name="effective_from") public LocalDate effectiveFrom; @Column(name="effective_to") public LocalDate effectiveTo; @Column(name="created_at",nullable=false) public Instant createdAt; protected UserRoleAssignment(){} public UserRoleAssignment(User u,Role r,String scope,Organization org,LocalDate from,LocalDate to){id=UUID.randomUUID();user=u;role=r;dataScope=scope;organization=org;effectiveFrom=from;effectiveTo=to;createdAt=Instant.now();} }
